// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *MaintenanceLedgerEntry) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := tables.CompanyTable(company, MaintenanceLedgerEntryTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (entry_no)`,
		fmt.Sprintf("%s$Maintenance_Ledger_Entry$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (fa_no, depreciation_book_code, fa_posting_date)`,
		fmt.Sprintf("%s$Maintenance_Ledger_Entry$fa_book_date", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index fa_book_date: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (fa_no, depreciation_book_code, posting_date)`,
		fmt.Sprintf("%s$Maintenance_Ledger_Entry$fa_book_posting_date", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index fa_book_posting_date: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (fa_no, depreciation_book_code, maintenance_code, fa_posting_date)`,
		fmt.Sprintf("%s$Maintenance_Ledger_Entry$fa_book_code_date", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index fa_book_code_date: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (fa_no, depreciation_book_code, maintenance_code, posting_date)`,
		fmt.Sprintf("%s$Maintenance_Ledger_Entry$fa_book_code_posting_date", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index fa_book_code_posting_date: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (document_no, posting_date)`,
		fmt.Sprintf("%s$Maintenance_Ledger_Entry$document", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index document: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (g_l_entry_no)`,
		fmt.Sprintf("%s$Maintenance_Ledger_Entry$g_l_entry", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index g_l_entry: %w", err)
	}
	var keys []sift.Key
	for _, spec := range maintenanceLedgerEntrySIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, MaintenanceLedgerEntryTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, MaintenanceLedgerEntryTableName, keys)
}

// maintenanceLedgerEntrySIFTSpecs are the table's keys with sum_index_fields
func maintenanceLedgerEntrySIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{
		{
			Name:   "fa_book_date",
			Fields: []sift.Column{{Name: "fa_no", Kind: sift.KindText}, {Name: "depreciation_book_code", Kind: sift.KindText}, {Name: "fa_posting_date", Kind: sift.KindDate}},
			Sums:   []sift.Column{{Name: "amount", Kind: sift.KindDecimal}},
		},
		{
			Name:   "fa_book_posting_date",
			Fields: []sift.Column{{Name: "fa_no", Kind: sift.KindText}, {Name: "depreciation_book_code", Kind: sift.KindText}, {Name: "posting_date", Kind: sift.KindDate}},
			Sums:   []sift.Column{{Name: "amount", Kind: sift.KindDecimal}},
		},
		{
			Name:   "fa_book_code_date",
			Fields: []sift.Column{{Name: "fa_no", Kind: sift.KindText}, {Name: "depreciation_book_code", Kind: sift.KindText}, {Name: "maintenance_code", Kind: sift.KindText}, {Name: "fa_posting_date", Kind: sift.KindDate}},
			Sums:   []sift.Column{{Name: "amount", Kind: sift.KindDecimal}},
		},
		{
			Name:   "fa_book_code_posting_date",
			Fields: []sift.Column{{Name: "fa_no", Kind: sift.KindText}, {Name: "depreciation_book_code", Kind: sift.KindText}, {Name: "maintenance_code", Kind: sift.KindText}, {Name: "posting_date", Kind: sift.KindDate}},
			Sums:   []sift.Column{{Name: "amount", Kind: sift.KindDecimal}},
		},
	}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *MaintenanceLedgerEntry) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := tables.CompanyTable(t.company, MaintenanceLedgerEntryTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range maintenanceLedgerEntrySIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, MaintenanceLedgerEntryTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: MaintenanceLedgerEntryTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, MaintenanceLedgerEntryTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

